@php $linePoints=collect($linePoints)->sortByDesc('year')->values(); @endphp
<div class="line-chart" data-line-chart><h3>{{ $lineTitle }}</h3><div class="chart-filter"><label>Measure<select>@foreach($lineMetrics as $key=>$label)<option value="{{ $key }}">{{ $label }}</option>@endforeach</select></label><label>From year<input type="number" min="{{ $linePoints->min('year')??1800 }}" max="{{ $linePoints->max('year')??2100 }}" value="{{ $linePoints->min('year')??1800 }}"></label></div><p data-chart-status role="status">Available records, most recent first. Missing figures are not zero.</p><div class="chart-scroll"><svg viewBox="0 0 700 260" role="img" aria-label="{{ $lineTitle }}"></svg></div><script type="application/json">{!! json_encode($linePoints,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) !!}</script><div class="chart-points">@foreach($linePoints as $point)<div data-year="{{ $point['year'] }}"><strong>@if(!empty($point['url']))<a href="{{ $point['url'] }}">{{ $point['label']??$point['year'] }}</a>@else{{ $point['label']??$point['year'] }}@endif</strong>@foreach($lineMetrics as $key=>$label)<div>{{ $label }}: {{ isset($point[$key])?number_format($point[$key],$key==='turnout'?2:0):'No data' }}</div>@endforeach</div>@endforeach</div></div>
